head.script:
/* 프로그램ID */
scwin.pgmId = 'PGJ196M01';

/* 최상단(opener, parent 포함) 기준 함수 */
scwin.isMain = function() {
    return true;
};

/* 페이지당 건수 */
scwin.pagaSize = '';
scwin.pageNum = 1;

/**
 * 나의동산집행정보 목록 페이지당 건수 처리
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.10.11.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.onpageload = function() {

    scscrno.setScPgmId(scwin.pgmId);

    /* 메뉴 */
    if(!scutilo.isEmpty(scwin.pgmId)){
        $p.main().wfm_side.scope.scwin.menuFocus(scwin.pgmId.slice(0,6));
    }

    let pageCnt = 10;
    if (scwin.getCookie('pageCnt')==null) {
        sbx_myMvprpLst.setValue('10');
    } else {
        pageCnt = Number(scwin.getCookie('pageCnt'));
        sbx_myMvprpLst.setValue(scwin.getCookie('pageCnt'));
    }

    scwin.pagaSize = pageCnt;
    scwin.myMvprpExecInfMain(true);
};

//웹접근성으로 인한 title제공 수정
scwin.titleFormatter = function(){
  return "";
}

function showTooltip(){
    const tooltipContent = document.querySelector('.w2grid_tooltip')
    tooltipContent.classList.add('on')
}

function hideTooltip(){
    const tooltipContent = document.querySelector('.w2grid_tooltip')
    tooltipContent.classList.remove('on')
}

