 * ============= ============ ==========================
 *  2024.09.04.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 *
 */
scwin.chargDept = function(data, formattedData, rowIndex, colIndex){
    return `${data}</br>연락처 : ${dlt_myMvprpCsLst.getCellData(rowIndex, "telNum")}`
}


/**
 *
 * 그리드 담당계 툴팁 생성하기위한 tooltipFormatter
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.09.04.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 *
 */
scwin.tooltipFormatter = function(rowIndex, colIndex, label, isOverflow){
  var txt = "";
  var _colId = dlt_myMvprpCsLst.getColumnID(colIndex);
  if(_colId == "deptNm"){
    const telNum = dlt_myMvprpCsLst.getCellData(rowIndex, "telNum");
    txt =`<div class="toolTipText">
        <span>·<text class="mr5" style="color:#6798FD; width:16px;">전화번호</text>${telNum}</span></div>`;
  }

  return txt;
}

/**
 * 페이지 번호 이동시 데이터 조회
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.10.11.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.pgl_myMvprpCsLst_onviewchange = function(info) {
    dma_pageInfo.set( "pageNo" , info.newSelectedIndex );
    dma_pageInfo.set( "bfPageNo",info.oldSelectedIndex );
    scwin.pageNum = info.newSelectedIndex;
    scwin.myMvprpExecInfMain(false);//조회처리
};


/**
 * 공지사항 목록 페이지 건수 쿠키 처리 set함수
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.10.11.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.setCookie = function(cookie_name, value, days) {
  var exdate = new Date();
  /* days의 1이 들어가면 10초 설정 */
  exdate.setTime(exdate.getTime() + days * 10 * 1000); //10초설정
  // 설정 일수만큼 현재시간에 만료값으로 지정 시간이 없을경우 계속
  var cookie_value = encodeURIComponent(value) + ((days == null) ? '' : '; expires=' + exdate.toUTCString());
  document.cookie = encodeURIComponent(cookie_name) + '=' + cookie_value;
}


/**
 * 공지사항 목록 페이지 건수 쿠키 처리 get함수
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.10.11.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.getCookie = function(cookie_name) {
  var x, y;
  var val = document.cookie.split(';');
  for (var i = 0; i < val.length; i++) {
    x = val[i].substr(0, val[i].indexOf('='));
    y = val[i].substr(val[i].indexOf('=') + 1);
    x = x.replace(/^\s+|\s+$/g, ''); // 앞과 뒤의 공백 제거하기
    if (x == cookie_name) {
      return unescape(y); // unescape로 디코딩 후 값 리턴
    }
  }
}

/**
 * 페이지당 선택시 회당 페이지크기 만큼 리스트 조회
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.10.11.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.sbx_myMvprpLst_onviewchange = function(info) {
    var cookieFlag = info.newValue;
    if (cookieFlag == 10) {
        scwin.setCookie('pageCnt','10');
    } else if (cookieFlag == 20) {
        scwin.setCookie('pageCnt','20');
    } else if (cookieFlag == 30) {
        scwin.setCookie('pageCnt','30');
    } else if (cookieFlag == 40) {
        scwin.setCookie('pageCnt','40');
    }
    scwin.pagaSize = scwin.getCookie('pageCnt');
    scwin.myMvprpExecInfMain(true);
};

/**
 * 추가 버튼 클릭시 추가 팝업창 open
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.10.11.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.click_myMvprpExecAdd = function(){
    let popId = "myMvprpExecAddPopUp";
    if(scwin.popupDpcnChk(popId)) {
        scwin.myMvprpExecAddPopUp();
    } else{
        return;
    }
}

/**
 * 삭제할 동산집행정보를 선택후 삭제 버튼 클릭시 유효성 검사 및 삭제
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.10.11.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.click_mvprpExecInfDel = function(){
    var cheLst = dlt_myMvprpCsLst.getMatchedIndex("checkBox", "1");
    if (cheLst.length<=0) {
        scutilo.showMsg(scglblo.MSG.WARN,"하나 이상의 물건을 선택하세요");
        return;
    } else {
        scutilo.showConfirm(scglblo.MSG.WARN,"삭제하시겠습니까?",scwin.realMyMvprpExecInfDel);
    }
}

/**
 * 삭제 유효성 확인에서 true일경우 삭제
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.10.11.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.realMyMvprpExecInfDel =function(e){
    let flag = e.clickValue;
    if (flag) {
        let cheLst = dlt_myMvprpCsLst.getMatchedIndex("checkBox", "1");
        dlt_myMvprpExecInfDel.removeAll();
        for (let i=0; i<cheLst.length; i++) {
            dlt_myMvprpExecInfDel.insertRow(i);
            dlt_myMvprpExecInfDel.setCellData(i, "cortOfcCd", dlt_myMvprpCsLst.getCellData(cheLst[i], "cortOfcCd"))
            dlt_myMvprpExecInfDel.setCellData(i, "csNo", dlt_myMvprpCsLst.getCellData(cheLst[i], "csNo"));
        }
        com.executeSubmission(sbm_deleteMvprpExecInf);
    }
}

/**
 * 나의동산집행정보 추가 popUp창
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.10.11.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.myMvprpExecAddPopUp = function(){

    /********* Popup Settings *********/
    var winW = window.innerWidth;
    var winH = window.innerHeight;

    /* small popup size */
    var popupW = 700;
    var popupH = 450;

    // /* default popup size */
    // var popupW = 900;
    // var popupH = 700;

    var popupX = (winW/2) - (popupW/2);
    var popupY = (winH/2) - (popupH/2);

    /**
     * 공지사항 openPopUp option설정
     */
    let options = {
        id: "myMvprpExecAddPopUp",
        type: "wframePopup",
        popupName: "나의동산 집행정보 추가",
        top:popupY,
        left:popupX,
        width:popupW,
        height:popupH,
        modal: false
    };

    com.win.openPopup("/pgj/ui/pgj100/PGJ196P02.xml",options);
}


/**
 * 팝업창 중복 생성 체크
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.10.11.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.popupDpcnChk = function(id){
    var popupList = WebSquare.uiplugin.popup.popupList;
    if (popupList.length!=0) {
        for (var idx = 0; idx < popupList.length; idx++) {
            if (WebSquare.uiplugin.popup.popupList[idx].id.indexOf(id) != -1) {
                return false;
            }
        }
    }
    return true;
}

