scwin.grd_myMvprpCsLst_oncellclick = function(row,col,colId) {
    if (col == 1) {
        let srch ={};
        srch.csNo = dlt_myMvprpCsLst.getCellData(dlt_myMvprpCsLst.getRowPosition(), "csNo");
        srch.cortOfcCd =  dlt_myMvprpCsLst.getCellData(dlt_myMvprpCsLst.getRowPosition(),"cortOfcCd");
        srch.auctnIntrpsDvsCd = dlt_myMvprpCsLst.getCellData(dlt_myMvprpCsLst.getRowPosition(), "auctnIntrpsDvsCd");
        srch.mvprpCsNo = dlt_myMvprpCsLst.getCellData(dlt_myMvprpCsLst.getRowPosition(), "mvprpCsNo");
        const popId = "mvprpExecInfDtlPopUp";
        if(scwin.popupDpcnChk(popId)) {
            scwin.mvprpExecInfDtlPopUp(srch);
        } else{
            return;
        }
     }
};

/**
