    var winH = window.innerHeight;

    /* small popup size */
    //var popupW = 700;
    //var popupH = 450;

    // /* default popup size */
    var popupW = 958;
    var popupH = 695;

    var popupX = (winW/2) - (popupW/2);
    var popupY = (winH/2) - (popupH/2);

    /**
     * 공지사항 openPopUp option설정
     */
    var options = {
        id: "mvprpExecInfDtlPopUp",
        type: "wframePopup",
        popupName: "대한민국법원 법원경매정보_나의동산집행정보",
        top:popupY,
        left:popupX,
        width:popupW,
        height:popupH,
        modal: true
    };

    // /* 공지사항 팝업창이 오픈될때 같이 가져갈 paramether 변수 선언 */
    //obj = {};
    // /* 공지사항 팝업창에서 closePopUp시 실행시킬 callback 함수 */
    // obj.callbackFn = "scwin.callbackFn";

    // /* 공지사항 팝업창이 오픈될때 같이 가져갈 paramether */
    paramObj = {};
    paramObj.csNo = srch.csNo;
    paramObj.cortOfcCd = srch.cortOfcCd;
    paramObj.mvprpCsNo = srch.mvprpCsNo;
    paramObj.auctnIntrpsDvsCd = srch.auctnIntrpsDvsCd;
    com.win.openPopup("/pgj/ui/pgj100/PGJ196F01.xml",options,paramObj);
}

/**
 *  페이지 인쇄 이벤트
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.0 5.22.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.printEvent = function(e) {
    let paramJSON = {};
    paramJSON.html = document.getElementById($p.getComponentById('grp_contests').id).innerHTML;

	const dataObject = {
		type : "json",
		data : paramJSON,
		name : "paramObj"
	};

    /* default popup size */
    const winW = window.innerWidth;
    const winH = window.innerHeight;
    const popupW = 1200;
    const popupH = 700;

    const popupX = (winW / 2) - (popupW / 2);
    const popupY = (winH / 2) - (popupH / 2);

	// 팝업의 옵션
	var options = {
			id: 'print',					// 팝업ID
			type: "browserPopup",			// 팝업 타입(wframePopup,browserPopup)
			width: popupW,				// 팝업 가로사이즈
			height: popupH,			// 팝업 세로사이즈
			top: popupY,					// 팝업 top위치
			left: popupX,				// 팝업 left위치
			popupName: "인쇄",				// 팝업 Name
			modal: false,					// 부모창이 안움직임(true)/부모창이 움직임(false)
			useIFrame: true,
			dataObject : dataObject
	};

	$p.openPopup("/pgj/ui/pgj100/PGJPrintContainer.xml", options);
};

